/** Built-in N3 demo policy. Bytes match `static/samples/sinosure-demo-policy.pdf`. */
export const DEMO_SINOSURE_FILE_NAME = '中信保演示示例保单.pdf';
export const DEMO_SINOSURE_SAMPLE_URL = '/static/samples/sinosure-demo-policy.pdf';

const DEMO_SINOSURE_PDF_BASE64 =
  '';

export function demoSinosurePdfBytes(): Uint8Array {
  const bin = atob(DEMO_SINOSURE_PDF_BASE64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export function isPdfBytes(bytes: Uint8Array): boolean {
  return (
    bytes.length > 5 &&
    bytes[0] === 0x25 &&
    bytes[1] === 0x50 &&
    bytes[2] === 0x44 &&
    bytes[3] === 0x46 &&
    bytes[4] === 0x2d
  );
}
